// src/logging.ts
import { Context, Formatter, Layer, Logger, References } from "effect";
var levels = {
  trace: "Trace",
  debug: "Debug",
  info: "Info",
  warn: "Warn",
  error: "Error",
  fatal: "Fatal"
};
var levelNames = new Map([
  [levels.trace, "trace"],
  [levels.debug, "debug"],
  [levels.info, "info"],
  [levels.warn, "warn"],
  [levels.error, "error"],
  [levels.fatal, "fatal"]
]);
function normalizeLevel(level) {
  return levelNames.get(level);
}
function layer3(log) {
  const logger = Logger.make((options) => {
    if (!log)
      return;
    const level = normalizeLevel(options.logLevel);
    if (!level)
      return;
    const entry = Logger.formatStructured.log(options);
    const values = Array.isArray(entry.message) ? entry.message : [entry.message];
    const [message, ...data] = values;
    const details = data.length === 1 && !Array.isArray(data[0]) ? data[0] : undefined;
    const { cause: detailCause, ...detailAttributes } = details ?? {};
    const attributes = {
      ...entry.annotations,
      ...detailAttributes,
      ...Object.keys(entry.spans).length > 0 ? { spans: entry.spans } : {},
      ...!details && data.length > 0 ? { data: data.length === 1 ? data[0] : data } : {}
    };
    try {
      log.emit({
        level,
        message: typeof message === "string" ? message : Formatter.format(message),
        ...Object.keys(attributes).length > 0 ? { attributes } : {},
        ...entry.cause === undefined && detailCause === undefined ? {} : { cause: entry.cause ?? detailCause }
      });
    } catch {}
  });
  return Layer.merge(Logger.layer([logger], { mergeWithExisting: false }), Layer.succeed(References.MinimumLogLevel, levels[log?.level ?? "info"]));
}
function context2(source) {
  return Context.make(Logger.CurrentLoggers, Context.get(source, Logger.CurrentLoggers)).pipe(Context.add(References.MinimumLogLevel, Context.get(source, References.MinimumLogLevel)));
}

export { layer3, context2 };
